const content = `
  <div class="flexcol">
    <h3>Rerolling a Skill:</h3>
    <p>Please pick a skill to reroll from the buttons below.<strong>It must match the one you chose when you took this trait.</strong></p>
  </div>
`;

async function getAnswer() {
  return Dialog.wait({
    title: `${item.name} – Reroll a Skill`,
    content: content,
    buttons: {
      dev: {
        label: pf1.config.skills["dev"],
        callback: () => "dev",
      },
      ken: {
        label: pf1.config.skills["ken"],
        callback: () => "ken",
      },
      umd: {
        label: pf1.config.skills["umd"],
        callback: () => "umd",
      }
    },
    default: 'dev',
    close: () => null,
  },
  {
     height: "auto",
     width: 680,
  });
}

const answer = await getAnswer();
if(answer !== null) {
  actor.rollSkill(answer);
} else {
  ui.notifications.warn(`No answer was selected. Restoring use of "${item.name}".`);
  await item.update({"system.uses.value": 1 });
}

const content = `
  <div class="flexcol">
    <h3>Rerolling a Saving Throw:</h3>
    <p>Please pick a saving throw to reroll from the buttons below.</p>
  </div>
`;

const labels = [game.i18n.localize("PF1.SavingThrowFort"), game.i18n.localize("PF1.SavingThrowRef"), game.i18n.localize("PF1.SavingThrowWill")];

async function getAnswer() {
  return Dialog.wait({
    title: `${item.name} – Reroll a Saving Throw`,
    content: content,
    buttons: {
      fort: {
        label: labels[0],
        callback: () => "fort",
      },
      ref: {
        label: labels[1],
        callback: () => "ref",
      },
      will: {
        label: labels[2],
        callback: () => "will",
      }
    },
    default: 'fort',
    close: () => null,
  },
  {
     height: "auto",
     width: 680,
  });
}

const answer = await getAnswer();
if(answer !== null) {
  actor.rollSavingThrow(answer);
} else {
  ui.notifications.warn(`No answer was selected. Restoring use of "${item.name}".`);
  await item.update({"system.uses.value": 1 });
}
